fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 8 {
            host::display::state_set(8 + i, (i * 37 + 11) % 100);
            i = i + 1;
        }
    }
    let mut ph = [0; 8];
    let mut i: i32 = 0;
    while i < 8 {
        ph[i] = host::display::state_get(8 + i);
        i = i + 1;
    }
    let mut fired: i32 = 0;
    i = 0;
    while i < 8 {
        ph[i] = ph[i] + 1;
        if ph[i] >= 100 {
            ph[i] = 0;
            fired = fired + 1;
        }
        i = i + 1;
    }
    if fired > 0 {
        i = 0;
        while i < 8 {
            if ph[i] != 0 {
                ph[i] = ph[i] + fired * 3;
                if ph[i] >= 100 { ph[i] = 99; }
            }
            i = i + 1;
        }
    }
    let mut lit: i32 = 0;
    i = 0;
    while i < 8 {
        host::display::state_set(8 + i, ph[i]);
        if ph[i] < 8 { lit = lit + 1; }
        i = i + 1;
    }
    host::display::clear(0x060a06);
    i = 0;
    while i < 8 {
        let x: i32 = w / 5 + (i % 4) * (w / 5);
        let y: i32 = h / 3 + (i / 4) * (h / 3);
        if ph[i] < 8 {
            host::display::fill_rect(x - 14, y - 14, 28, 28, 0x404810);
            host::display::fill_rect(x - 7, y - 7, 14, 14, 0xf0ff50);
        } else {
            let g: i32 = 30 + ph[i];
            host::display::fill_rect(x - 5, y - 5, 10, 10, g * 65536 + g * 256 + g / 2);
        }
        i = i + 1;
    }
    host::display::draw_string(8, 8, "FLASHING NOW", 0x607060, 1);
    host::display::draw_number(130, 8, lit, 0xf0ff50, 1);
    host::display::present();
}
